CREATE INDEX IF NOT EXISTS idx_patients_status_admission_time ON public.patients (status, admission_time DESC);
CREATE INDEX IF NOT EXISTS idx_patients_facility_status_admission_time ON public.patients (facility_name, status, admission_time DESC);
CREATE INDEX IF NOT EXISTS idx_patients_admission_time_desc ON public.patients (admission_time DESC);
CREATE INDEX IF NOT EXISTS idx_patients_facility_admission_time ON public.patients (facility_name, admission_time DESC);
CREATE INDEX IF NOT EXISTS idx_patients_discharge_time_desc ON public.patients (discharge_time DESC) WHERE discharge_time IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_lab_orders_patient_created ON public.lab_orders (patient_mrn, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_lab_orders_facility_status_created ON public.lab_orders (facility_name, status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_lab_orders_facility_resulted_created ON public.lab_orders (facility_name, resulted_at DESC, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_medication_orders_patient_created ON public.medication_orders (patient_mrn, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_medication_orders_facility_status_created ON public.medication_orders (facility_name, status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_bed_management_facility_status_room ON public.bed_management (facility_name, status, room_number, bed_letter);
CREATE INDEX IF NOT EXISTS idx_custom_value_sets_created ON public.custom_value_sets (created_at DESC);
CREATE INDEX IF NOT EXISTS idx_nlp_audit_logs_status_created ON public.nlp_audit_logs (status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_nlp_audit_logs_patient_created ON public.nlp_audit_logs (patient_mrn, created_at DESC);